(()=>{const box=document.createElement('aside');box.style='position:fixed;top:5px;left:5px;z-index:400;background:white;color:#123;max-width:280px;max-height:190px;overflow:auto;padding:8px';box.innerHTML='<button id="armProbe">记录下一次行动的帧</button><pre id="motionFrames" style="white-space:pre-wrap">未开始</pre>';document.body.appendChild(box);const h=window.__wolfTest;const menu=document.createElement('div');menu.innerHTML=['two','grass','mask','swap','large'].map(x=>'<button data-scene="'+x+'">'+({two:'2×2双羊',grass:'高草',mask:'混入羊群',swap:'幻影换位',large:'11×11'})[x]+'</button>').join('');box.prepend(menu);menu.onclick=e=>{const id=e.target.dataset.scene;if(!id)return;h.dismissAllGuides();h.setDifficulty('hard');h.load(id==='large'?12:id==='swap'?8:'t3');h.clean();h.start();h.clean();if(id!=='large'){const cells=id==='two'?[[0,0],[2,2],[3,2],[2,3],[3,3]]:Array.from({length:25},(_,i)=>[1+i%5,1+Math.floor(i/5)]);const open=new Set(cells.map(p=>p.join(','))),voids=new Set();for(let y=0;y<7;y++)for(let x=0;x<7;x++)if(!open.has(x+','+y)&&!(x===0&&y===0))voids.add(x+','+y);h.patch({voids,walls:new Set(),fences:new Set(),gates:new Map(),round:2,wolf:{x:0,y:0},wolfBeforeAction:{x:0,y:0},guard:null,otherGuard:id==='mask'?{id:'guardB',p:{x:4,y:4},home:{x:4,y:4},state:'masked',personality:'bold',snared:0,mask:true,stress:0}:null,grassPatches:new Set(id==='grass'?['2,2','3,2']:[]),sheep:[{id:0,real:true,x:2,y:2,snared:0,stress:0},{id:1,real:false,x:3,y:3,snared:0,stress:0}],swapPressure:10,swapCooldown:0,swapWarning:null});if(id==='swap'){h.patch({wolf:{x:5,y:5}});h.prepareSwapEvent()}}h.render()};let armed=false,recording=false;document.getElementById('armProbe').onclick=()=>{armed=true;document.getElementById('motionFrames').textContent='已准备，请执行游戏行动'};new MutationObserver(()=>{if(!armed||recording)return;armed=false;recording=true;const frames=[],begin=performance.now();function frame(){const time=performance.now()-begin;frames.push({time,actors:[...document.querySelectorAll('.sheep-motion')].map(e=>({from:e.dataset.from,to:e.dataset.to,transform:getComputedStyle(e).transform,rect:e.getBoundingClientRect().toJSON()}))});if(time<350)requestAnimationFrame(frame);else{recording=false;document.getElementById('motionFrames').textContent=JSON.stringify(frames)}}requestAnimationFrame(frame)}).observe(document.getElementById('board'),{childList:true,subtree:true});})();